#include "stdafx.h"#include <rsuNoNames.h>#include "SM_Server.h"#include <rsuMemoryManager.h>#include <MemoryServiceSM5xx.h>#include <ConnectSM.h>#pragma comment( lib, "ConnectSM5xx.lib")#ifdef _MANAGED#pragma managed(push, off)#endifHINSTANCE g_hInst = 0;BOOL APIENTRY DllMain( HMODULE hModule,                       DWORD  ul_reason_for_call,                       LPVOID lpReserved					 ){  switch (ul_reason_for_call)  {  case DLL_PROCESS_ATTACH:    g_hInst = hModule;    LoadLibrary("H5xxServerMemCtrl.dll");    break;  case DLL_THREAD_ATTACH:  case DLL_THREAD_DETACH:  case DLL_PROCESS_DETACH:    break;  }  return TRUE;}#ifdef _MANAGED#pragma managed(pop)#endifKNoName g_IOs;static KRsuMemoryManager s_memoryHW;static void* _ObjsMemAllocatorHW( size_t size ){  void* p = s_memoryHW.AllocMemory( (DWORD)size );  ASS( p );  return p;}static FILE *pLog = NULL;static CBase* _IOsStructAllocatorImpl( LPCSTR pszArmName, LPCSTR pszShortSmName, DWORD TypeID, int number ){  if( !pLog )  {    char szPath[MAX_PATH];    _makepath_s( szPath, NULL, rsuGetMemoryPath(), "SM5tegs", "csv" );    fopen_s( &pLog, szPath, "wt" );  }  if( pLog && pszArmName && *pszArmName )  {    fprintf_s( pLog, "%s;%d\n", pszArmName, TypeID );    fflush( pLog );  }  CBase *pObj = NULL;  if( pszArmName && *pszArmName )  {    pObj = g_IOs.CreateStruct( pszArmName, TypeID, number );    if( pszShortSmName && *pszShortSmName )    {      int r = g_IOs.CreateRefToData( pszShortSmName, pObj );      KKK();    }  }  else    pObj = g_IOs.CreateStruct( pszShortSmName, TypeID, number );  return pObj;}//////////////////////////////////////////////////////////////////////////static bool s_bConstructedMemory = false;extern "C" Q_DECL_EXPORT         IRsuModel* CreateServer(LPCSTR ObjName ){  if( !s_bConstructedMemory )  {    s_memoryHW.Create( "SM5xx_Mem", 8 );    g_IOs = KNoName::Create( "SM5xx_IOs", true );    g_IOs.Reset();    KMemoryServiceSM5xx::Instance().InitMemAllocator( _ObjsMemAllocatorHW );    KMemoryServiceSM5xx::Instance().InitIOsStructAllocator( _IOsStructAllocatorImpl );    s_bConstructedMemory = true;    if( !pRegisterSMstructs )      LoadLibrary("SM5xxRegisterInRSU.dll");    if( pRegisterSMstructs )      pRegisterSMstructs();  }  IRsuModel *pModel = new KServer( ObjName );  return pModel;}